import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Plane geometry: 512px → 2 units, 320px → 1.25 units
  const geometry = new PlaneGeometry(2, 1.25);

  // Material with image texture
  const material = new MeshBasicNodeMaterial({
    toneMapped: true,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load and apply image texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
